{"command":"cd /workspace
cat <<'EOF' > /tmp/Inspect.java
import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.File;
public class Inspect {
 public static void main(String[] args) throws Exception {
   for (String path: args) {
     File f = new File(path);
     if (!f.exists()) { System.out.println(path+" not exists"); continue; }
     BufferedImage img = ImageIO.read(f);
     if (img==null) { System.out.println(path+" not image, size "+f.length()); continue; }
     System.out.println(path+" -> "+img.getWidth()+"x"+img.getHeight()+" type "+img.getType());
   }
 }
}
EOF
javac /tmp/Inspect.java -d /tmp
java -cp /tmp Inspect /tmp/simple.png /tmp/simple2.png /tmp/simple3.png /tmp/simple4.png /tmp/simple_scale.png /tmp/out.png /tmp/input.png /tmp/overwrite_test.png /tmp/tab.png /tmp/ow.png /tmp/simple12.png
java -cp /tmp Inspect /tmp/out.svg 2>&1 | head
# also inspect svg
head -n 100 /tmp/out.svg
ls /tmp/*.svg | head
cat /tmp/out.svg | head -n 100
"}

